        id="allPermission"
        [(ngModel)]="grantAllPermissions"
        (onChange)="changeGrantAllPermissions()"
      />
      <label class="form-check-label" for="allPermission"> Tüm izinleri ver </label>
    </div>

  </div>
  <div class="card-body">
    <div class="row">
      <div class="col-md-3">
        <ul ngbNav #verticalNav="ngbNav" [activeId]="1" class="nav flex-column nav-pills text-center">
          <li *ngFor="let x of groups; let i = index" [ngbNavItem]="i+1">
              <a ngbNavLink class="mb-2"  (click)="changeDisplays(x.name)">
