                      id="selectAll"
                      [(ngModel)]="selectAllPermissions"
                        (onChange)="changeSelectAllPermissions()"
                    />
                    <label class="form-check-label" for="selectAll"> Hepsini seç </label>
                  </div>
                
                  <div class="row" style="padding-left: 10px;">
                    <div class="col-md-12 field-checkbox" *ngFor="let p of selectedPermissions">
                      <div class="form-check mb-3">
                        <input
                          class="form-check-input"
                          type="checkbox"
                          id="selectAll"
                          [(ngModel)]="p.isGranted"
                          [disabled]="p.isDisabled"
                          inputId="{{ p.name }}"
                          (onChange)="changeChilds(p)"
                        />
                        <label class="form-check-label" for="{{ p.name }}">{{ p.displayName }} </label>
                      </div>

                    </div>
                  </div>
                </div>
              </ng-template>
          </li>
